(()=>{'use strict';let scheduled=false;function sync(){scheduled=false;const root=document.getElementById('main-content');if(!root)return;const row=root.querySelector('.pati-ig-profile .pati-own-profile-actions');if(row){const buttons=[...row.querySelectorAll(':scope > button')];const edit=buttons.find(b=>/^(profili\s*)?düzenle$/i.test((b.textContent||'').trim()));const stats=buttons.find(b=>/istatistik/i.test(b.textContent||''));if(edit){if(edit.textContent!=='Düzenle')edit.textContent='Düzenle';edit.classList.add('buchee-main-profile-action');edit.style.order='0'}if(stats){stats.classList.add('buchee-main-profile-action');stats.style.order='1'}buttons.filter(b=>b!==edit&&b!==stats).forEach((b,i)=>b.style.order=String(i+2))}
const actions=root.querySelectorAll('.buchee-chat-popover [data-action="pati-group-create-open"],.buchee-chat-popover button');for(const b of actions){if(!/yeni\s*grup/i.test(b.textContent||''))continue;if(b.querySelector('.buchee-group-menu-icon'))continue;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','2');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.classList.add('buchee-group-menu-icon');svg.innerHTML='<circle cx="9" cy="8" r="3"/><path d="M3 19v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M17 15h5m-2.5-2.5v5"/>';const label=document.createElement('span');label.className='buchee-group-menu-label';label.textContent='Yeni grup';b.replaceChildren(svg,label);b.setAttribute('aria-label','Yeni grup oluştur')}
}function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(sync)}const target=document.getElementById('main-content')||document.body;new MutationObserver(schedule).observe(target,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',schedule);schedule()})();